package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.world.*;import net.minecraft.world.item.*;import net.minecraft.world.entity.player.Player;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.level.*;import net.minecraft.world.phys.*;import net.minecraft.core.*;
public final class Gad01Item extends Item {
 public static net.minecraft.nbt.CompoundTag saved(ItemStack stack){var legacy=stack.getTagElement("EntityTag");var n=BlockItem.getBlockEntityData(stack);return legacy!=null?legacy:n!=null&&n.contains("Entity",10)?n.getCompound("Entity"):null;}
 public static int stateHash(ItemStack stack){return stack.hasTag()?stack.getTag().hashCode():0;}
 public static void store(ItemStack stack,net.minecraft.nbt.CompoundTag data){stack.getOrCreateTag().put("EntityTag",data);}
 public Gad01Item(Properties p){super(p);}
 @Override public InteractionResult useOn(net.minecraft.world.item.context.UseOnContext c){return c.getPlayer()==null?InteractionResult.PASS:use(c.getLevel(),c.getPlayer(),c.getHand()).getResult();}
 @Override public InteractionResultHolder<ItemStack> use(Level l,Player p,InteractionHand h){var stack=p.getItemInHand(h);if(l.isClientSide)return InteractionResultHolder.success(stack);if(!(p instanceof ServerPlayer sp)||!p.isAlive()||p.isSpectator()||!p.mayBuild())return InteractionResultHolder.fail(stack);var hit=getPlayerPOVHitResult(l,p,ClipContext.Fluid.NONE);if(hit.getType()!=HitResult.Type.BLOCK||hit.getDirection()!=Direction.UP)return fail(p,stack);var pos=hit.getBlockPos().above();if(!l.mayInteract(p,pos)||!p.mayUseItemAt(pos,Direction.UP,stack))return fail(p,stack);var g=AddonEntities.GAD01.get().create(l);if(g==null)return fail(p,stack);
  var saved=Gad01Item.saved(stack);if(saved!=null){var data=saved.copy();for(String key:new String[]{"UUID","Pos","Motion","Rotation","Passengers"})data.remove(key);g.load(data);}else g.setEnergy(0);if(!g.permitted(sp))return fail(p,stack);Vec3 at=hit.getLocation().add(0,.005,0);g.moveTo(at.x,at.y,at.z,p.getYRot(),0);g.yRotO=g.getYRot();g.setZRot(0);g.setDeltaMovement(Vec3.ZERO);g.releaseControl();g.updateOBB();
  var body=g.getBoundingBox();var clear=new AABB(body.minX,body.minY,body.minZ,body.maxX,at.y+1.65,body.maxZ);if(clear.minY<l.getMinBuildHeight()||clear.maxY>l.getMaxBuildHeight()||!l.noCollision(g,clear))return fail(p,stack);
  if(!l.getWorldBorder().isWithinBounds(g.getBoundingBox())||!l.hasChunksAt(BlockPos.containing(g.getBoundingBox().minX,g.getBoundingBox().minY,g.getBoundingBox().minZ),BlockPos.containing(g.getBoundingBox().maxX,g.getBoundingBox().maxY,g.getBoundingBox().maxZ))||!l.noCollision(g,g.getBoundingBox())||!l.getEntities(g,g.getBoundingBox(),e->e.isPickable()&&!e.isSpectator()).isEmpty())return fail(p,stack);
  for(double x:new double[]{-.49,.49})for(double z:new double[]{-.4,.4}){var v=g.getVehicleTransform(1).transformPosition(new org.joml.Vector3d(x,.1,z));var ground=l.clip(new ClipContext(new Vec3(v.x,v.y,v.z),new Vec3(v.x,v.y-.3,v.z),ClipContext.Block.COLLIDER,ClipContext.Fluid.NONE,g));if(ground.getType()!=HitResult.Type.BLOCK||Math.abs(ground.getLocation().y-at.y)>.1)return fail(p,stack);}
  g.claimOwner(sp);SbwCompat.ensureDroneOwner(g,sp);if(!l.addFreshEntity(g))return fail(p,stack);if(!p.getAbilities().instabuild)stack.shrink(1);return InteractionResultHolder.consume(stack);
 }
 private static InteractionResultHolder<ItemStack> fail(Player p,ItemStack s){p.displayClientMessage(net.minecraft.network.chat.Component.translatable("gad01.placement"),true);return InteractionResultHolder.fail(s);}
 @Override public void initializeClient(java.util.function.Consumer<net.minecraftforge.client.extensions.common.IClientItemExtensions> c){c.accept(new net.minecraftforge.client.extensions.common.IClientItemExtensions(){public net.minecraft.client.renderer.BlockEntityWithoutLevelRenderer getCustomRenderer(){return Gad01ItemRenderer.instance();}});}
}
